export type SinuaBeaconPattern =
  | "notifying"
  | "reconnecting"
  | "locating"
  | "scanning"
  | "broadcasting";

/** Beacon parameters; unset ones keep the pattern's values. */
export interface SinuaBeaconParams {
  /** Centre dot radius as a fraction of the frame. Range notifying 0.01...0.4, reconnecting 0.01...0.4, locating 0.01...0.4, scanning 0.004...0.08, broadcasting 0.01...0.3. */
  dotSize?: number;
  /** Ink hue in degrees; applies once saturation is above 0. Range 0...360 (deg). */
  hue?: number;
  /** How present the whole visual is: 1 draws it as the pattern defines it, lower fades everything including its halos. A voice assistant rests below 1 when idle and comes to full ink when it listens. Range 0...1 (fraction). */
  ink?: number;
  /** Ripples per ping. Range notifying 1...4, scanning 1...8. Patterns: notifying, scanning. */
  ringCount?: number;
  /** How far the ink moves from grey toward the hue (0 = the grey ink). Range 0...1 (fraction). */
  saturation?: number;
  /** Seconds between pings. Range 0.05...30 (s). */
  period?: number;
  /** Play one ripple and stop (restart the clock to replay). Patterns: notifying. */
  once?: boolean;
  /** How far the ripples travel, as a fraction of the frame. Range 0.05...0.5 (fraction). Patterns: notifying. */
  ringReach?: number;
  /** Ripple stroke width as a fraction of the frame. Range 0.005...0.2 (fraction). Patterns: notifying, locating. */
  ringWidth?: number;
  /** Connection quality 0 to 1: lit segments and a calmer pulse as it rises. Range 0...1 (fraction). Patterns: reconnecting. */
  quality?: number;
  /** Gap between quality segments, in degrees. Range 0...60 (deg). Patterns: reconnecting. */
  segmentGap?: number;
  /** Radius of the quality arc as a fraction of the frame. Range 0.05...0.5 (fraction). Patterns: reconnecting. */
  segmentRadius?: number;
  /** Stroke width of the quality segments. Range 0.005...0.2 (fraction). Patterns: reconnecting. */
  segmentWidth?: number;
  /** Location accuracy 0 to 1: the halo shrinks as it rises. Range 0...1 (fraction). Patterns: locating. */
  accuracy?: number;
  /** Opacity of the accuracy halo. Range 0...1 (fraction). Patterns: locating. */
  haloOpacity?: number;
  /** How many targets were found (e.g. nearby devices): one blip each, lit as the sweep passes. 0 = still looking. Range 0...12. Patterns: scanning. */
  blipCount?: number;
  /** Seed for where the blips sit. Range 0...1000000. Patterns: scanning. */
  seed?: number;
  /** Draw the trail as one filled gradient wedge. Patterns: scanning. */
  trailFill?: boolean;
  /** Length of the sweep's fading trail, in degrees. Range 0...360 (deg). Patterns: scanning. */
  trailLength?: number;
  /** Waves stay lit as they build up instead of travelling. Patterns: broadcasting. */
  cumulative?: boolean;
  /** Opacity of the waves that aren't lit. Range 0...1 (fraction). Patterns: broadcasting. */
  inactiveOpacity?: number;
  /** Broadcast to one side or both. Range 1...2. Patterns: broadcasting. */
  sides?: number;
  /** Waves per side. Range 1...8. Patterns: broadcasting. */
  waveCount?: number;
  /** Waves travel inward. Patterns: broadcasting. */
  reversing?: boolean;
  /** Signal level 0 to 1 (how many waves are lit); below 0 = animate on its own. Range -1...1 (fraction). Patterns: broadcasting. */
  level?: number;
  /** Wave stroke width as a fraction of the frame. Range 0.01...0.4 (fraction). Patterns: broadcasting. */
  strokeWidth?: number;
  /** Arc of each wave in degrees. Range 10...180 (deg). Patterns: broadcasting. */
  waveSweep?: number;
  glow?: SinuaGlow;
  noise?: SinuaNoise;
  pulse?: SinuaPulse;
  gradient?: SinuaGradient;
  color?: SinuaColor;
}

